"""
Purpose: Install git pre-commit hook running documentation and architecture checks.
Inputs: Project root repository structure.
Outputs: Executable pre-commit hook in .git/hooks/.
Depends on: os, pathlib, stat, sys
Used by: None
Config keys: None
Tests: tests/unit/test_docs_and_architecture.py
"""

import os
import stat
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
GIT_DIR = PROJECT_ROOT / ".git"
HOOKS_DIR = GIT_DIR / "hooks"
PRE_COMMIT_HOOK = HOOKS_DIR / "pre-commit"

HOOK_CONTENT = """#!/bin/sh
# Auto-generated by tools/install_hooks.py
set -e

echo "[pre-commit] Checking documentation integrity..."
python tools/update_docs.py --check

echo "[pre-commit] Checking architecture rules..."
python tools/check_architecture.py

echo "[pre-commit] All checks passed."
"""


def install_hooks() -> int:
    if not GIT_DIR.exists():
        print(f"Error: {GIT_DIR} not found. Please run 'git init' first.")
        return 1

    HOOKS_DIR.mkdir(parents=True, exist_ok=True)
    PRE_COMMIT_HOOK.write_text(HOOK_CONTENT, encoding="utf-8")

    # Make executable on Unix-like environments
    try:
        current_stat = os.stat(PRE_COMMIT_HOOK)
        os.chmod(PRE_COMMIT_HOOK, current_stat.st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    except Exception:
        pass

    print(f"Successfully installed pre-commit hook at {PRE_COMMIT_HOOK}")
    return 0


if __name__ == "__main__":
    sys.exit(install_hooks())
